-- Шаг 75: курс и общие замечания PageSpeed (не только скорость). Повторный запуск ничего не меняет.
-- 1) иконки merit.svg в баннерах курса (banner-study) и удаления тату (banner-interial-category-new) — width / height 34×32: место
--    под иконку занято сразу (иначе, догрузившись, она сдвигала текст — CLS 0,13 на курсе — и баннер вырастал, LCP засчитывался заново);
UPDATE Impulse_Digital_X_site_htmlsnippets SET snippet = REPLACE(snippet, '<img src=\"/images/design/merit.svg\" alt=\"merit\">', '<img src=\"/images/design/merit.svg\" width=\"34\" height=\"32\" alt=\"merit\">') WHERE name = 'banner-study';
UPDATE Impulse_Digital_X_site_htmlsnippets SET snippet = REPLACE(snippet, '<img src=\"/images/design/merit.svg\" alt=\"merit\">', '<img src=\"/images/design/merit.svg\" width=\"34\" height=\"32\" alt=\"merit\">') WHERE name = 'banner-interial-category-new';
-- 2) шаблон «Обучение» (15): убран Google Maps (карты на странице нет — initMap падал с ошибкой в консоли, ~250 КБ JS впустую);
--    lightbox.js?v=2 (в lightbox.js у кнопки закрытия — role="button", для проверки «ссылки без href»);
UPDATE Impulse_Digital_X_site_templates SET content = REPLACE(REPLACE(content, '    <script defer src=\"https://maps.googleapis.com/maps/api/js?key=AIzaSyB3aTlJzCMv6opFNcZtoI-gzymZOc9nSNA&language=uk&region=UA&callback=initMap\"></script>\n', ''), '<script src=\"/assets/templates/js/lightbox.js\"></script>', '<script src=\"/assets/templates/js/lightbox.js?v=2\"></script>') WHERE id = 15;
-- 3) чанк inttelinput (поле телефона на всех формах): на телефонах список стран попадает в документ только при открытии, а ссылки
--    aria-owns / aria-controls / aria-activedescendant на него стоят всегда → «недействительные значения aria-*» (специальные
--    возможности, «агентный просмотр»). Пока списка в документе нет — ссылки снимаем, при открытии возвращаем.
UPDATE Impulse_Digital_X_site_htmlsnippets SET snippet = REPLACE(REPLACE(snippet, 'var inputs = document.querySelectorAll(\"[name=\'phone\']\");\n', '// шаг 75: на телефонах intlTelInput добавляет список стран в документ только при открытии, а ссылки aria-owns / aria-controls /\n// aria-activedescendant на него стоят всегда (PageSpeed: «недействительные значения aria-*»). Пока списка нет — ссылки снимаем.\nvar itiAria = function (input) {\n    var flag = input.parentNode.querySelector(\'.iti__selected-flag\');\n    var list = flag ? flag.getAttribute(\'aria-controls\') : \'\';\n    if (!list || !window.MutationObserver) return;\n    var strip = function () {\n        if (document.getElementById(list)) return;\n        [\'aria-owns\', \'aria-controls\', \'aria-activedescendant\'].forEach(function (a) {\n            if (flag.hasAttribute(a)) flag.removeAttribute(a);\n        });\n    };\n    new MutationObserver(strip).observe(flag, { attributes: true, attributeFilter: [\'aria-activedescendant\'] });\n    input.addEventListener(\'open:countrydropdown\', function () {\n        flag.setAttribute(\'aria-owns\', list);\n        flag.setAttribute(\'aria-controls\', list);\n    });\n    input.addEventListener(\'close:countrydropdown\', strip);\n    strip();\n};\nvar inputs = document.querySelectorAll(\"[name=\'phone\']\");\n'), '    let width = $(block).parents(\'form\').width();\n', '    itiAria(block);\n    let width = $(block).parents(\'form\').width();\n') WHERE name = 'inttelinput' AND snippet NOT LIKE '%itiAria%';
